(function () {
  'use strict';

  // On quickstart pages, move the autogenerated "All quickstarts" back-link
  // badge from the top of the MDX body into the page header, above the title
  // (where breadcrumbs would normally render).
  //
  // The original anchor is React-owned, so it is hidden in place and a clone
  // is inserted into the header — moving the node itself would crash React
  // when it unmounts the page.

  var CLONE_ID = 'qs-back-eyebrow';
  var QS_PATH = /^(?:\/docs)?(?:\/(?:es|ja|ko|pt-BR|ru|zh))?\/get-started\/quickstarts\/([^/]+)$/;

  function apply() {
    var clone = document.getElementById(CLONE_ID);
    var match = window.location.pathname.replace(/\/+$/, '').match(QS_PATH);
    var header = document.getElementById('header');
    var content = document.getElementById('content');

    if (!match || match[1] === 'home' || !header || !content) {
      if (clone) clone.remove();
      return;
    }

    // Only the top badge is a direct child of #content; the "All quickstarts"
    // link at the bottom of the page is nested in a wrapper div.
    var src = content.querySelector(':scope > a[href$="/get-started/quickstarts/home"]');
    if (!src) {
      if (clone) clone.remove();
      return;
    }

    if (src.style.display !== 'none') {
      src.style.display = 'none';
      src.setAttribute('aria-hidden', 'true');
    }

    // Already in place for this page (href carries the locale prefix).
    if (clone && header.contains(clone) && clone.getAttribute('href') === src.getAttribute('href')) {
      return;
    }
    if (clone) clone.remove();

    clone = src.cloneNode(true);
    clone.id = CLONE_ID;
    clone.style.display = 'block';
    clone.style.width = 'fit-content';
    clone.style.marginBottom = '0.75rem';
    clone.removeAttribute('aria-hidden');

    // Fix href for basePath deployments (e.g. /docs prefix in production).
    var base = window.location.pathname.startsWith('/docs') ? '/docs' : '';
    var dest = base + '/get-started/quickstarts/home';
    clone.setAttribute('href', dest);
    clone.addEventListener('click', function (e) {
      e.preventDefault();
      window.location.href = dest;
    });

    header.insertBefore(clone, header.firstChild);
  }

  function init() {
    apply();
    // Re-apply across SPA navigations / React re-renders. apply() is
    // idempotent, so observer feedback loops settle immediately.
    new MutationObserver(apply).observe(document.documentElement, {
      childList: true,
      subtree: true,
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();